# --- 1/4: supabase/migrations/20261007120000_gallery_sets.sql
[IO.File]::WriteAllBytes("$PWD\supabase\migrations\20261007120000_gallery_sets.sql", [Convert]::FromBase64String(""))

# --- 2/4: src/routes/gallery.tsx
[IO.File]::WriteAllBytes("$PWD\src\routes\gallery.tsx", [Convert]::FromBase64String(""))

# --- 3/4: src/components/GalleryShowcase.tsx
[IO.File]::WriteAllBytes("$PWD\src\components\GalleryShowcase.tsx", [Convert]::FromBase64String(""))

# --- 4/4: src/components/GalleryManager.tsx
[IO.File]::WriteAllBytes("$PWD\src\components\GalleryManager.tsx", [Convert]::FromBase64String(""))

# --- 5/5: wire up home page (nav links -> /gallery, remove old inline section)
$f = "$PWD\src\routes\index.tsx"
$c = [IO.File]::ReadAllText($f)
$c = $c.Replace('import GallerySection from "@/components/GallerySection";', '').Replace('<GallerySection />', '')
$c = [regex]::Replace($c, '<a href="#gallery"([^>]*)>(\s*)Gallery(\s*)</a>', '<Link to="/gallery"$1>$2Gallery$3</Link>')
[IO.File]::WriteAllText($f, $c, (New-Object Text.UTF8Encoding $false))
Remove-Item "$PWD\src\components\GallerySection.tsx" -ErrorAction SilentlyContinue
Write-Host "Gallery patch applied." -ForegroundColor Green
